 */

/**
 * @typedef {Object} CartItemInput - Payload received from POS UI when "Add to Cart" clicked
 * @property {string} id - Menu Item ID (e.g., "item_burger")
 * @property {string} name
 * @property {number} basePrice
 * @property {ModifierGroup[]} selectedModifiers - **ONLY groups where user made a selection**
