## 3. CORE IMPLEMENTATION: `src/utils/cartUtils.js`

**This is the most critical file. It must be pure, deterministic, and side-effect free.**

```javascript
// src/utils/cartUtils.js

/**
 * Normalizes an array of objects by sorting them by 'id' to ensure deterministic ordering.
 * @template T
 * @param {T[]} arr - Array of objects with 'id' property
 * @returns {T[]} New sorted array
 */
function _sortById(arr = []) {
  return [...arr].sort((a, b) => String(a.id).localeCompare(String(b.id)));
}

/**
 * Builds a canonical, sortable signature string from the variable parts of a cart item.
 * Format: `mods:<sorted_mod_option_ids>|addons:<sorted_addon_ids>|instr:<sanitized_instructions>`
 * @param {CartItemInput} item
 * @returns {string}
 */
export function buildLineSignature(item) {
  // 1. Modifiers: Flatten selected options across groups, sort by option ID
  // We only care about the *selected option IDs* for identity.
  const modOptionIds = (item.selectedModifiers || [])
    .flatMap(group => (group.selectedOptions || []).map(opt => opt.id))
    .filter(Boolean); // Guard against nulls

  // 2. Add-ons: Sort by addon ID
  const addonIds = (item.selectedAddOns || [])
    .map(addon => addon.id)
    .filter(Boolean);

  // 3. Special Instructions: Trim, lowercase, collapse whitespace for stability
  const instructions = (item.specialInstructions || '').trim().toLowerCase().replace(/\s+/g, ' ');

  const sortedMods = _sortById(modOptionIds.map(id => ({ id }))).map(o => o.id).join(',');
  const sortedAddons = _sortById(addonIds.map(id => ({ id }))).map(o => o.id).join(',');

  // Delimiters chosen to not conflict with typical ID chars (alphanum, underscore, hyphen)
  return `mods:${sortedMods}|addons:${sortedAddons}|instr:${instructions}`;
}

/**
 * Builds the final, stable, unique Line ID used as React Key and Reducer Map Key.
 * Format: `line_<itemId>__<signatureHash>`
 * Uses a simple hash (djb2) of signature to keep key length manageable and avoid char escaping issues.
 * @param {CartItemInput} item
 * @returns {string}
 */
export function buildLineId(item) {
  const signature = buildLineSignature(item);

  // Simple, fast, deterministic hash (djb2) - returns unsigned 32-bit int as string
  let hash = 5381;
  for (let i = 0; i < signature.length; i++) {
    hash = ((hash << 5) + hash) + signature.charCodeAt(i); // hash * 33 + char
    hash = hash & hash; // Convert to 32bit integer
  }
  // Ensure positive
  const hashStr = (hash >>> 0).toString(36); // Base36 for shorter string

  return `line_${item.id}__${hashStr}`;
}

/**
 * Calculates the total price for a single line configuration (quantity = 1).
 * @param {CartItemInput | CartLine} item
 * @returns {number}
 */
export function calculateLineUnitPrice(item) {
  const base = Number(item.basePrice) || 0;
  const modPrice = (item.selectedModifiers || [])
    .flatMap(g => g.selectedOptions || [])
    .reduce((sum, opt) => sum + (Number(opt.price) || 0), 0);
  const addonPrice = (item.selectedAddOns || [])
    .reduce((sum, addon) => sum + ((Number(addon.price) || 0) * (Number(addon.quantity) || 1)), 0);

  return base + modPrice + addonPrice;
}

/**
 * Factory to create a full CartLine object from input, attaching computed fields.
 * @param {CartItemInput} input
 * @returns {CartLine}
 */
export function createCartLine(input) {
  const lineId = buildLineId(input);
  const unitPrice = calculateLineUnitPrice(input);
  const qty = Number(input.quantity) || 1;

  return {
    lineId,
    itemId: input.id,
    name: input.name,
    basePrice: input.basePrice,
    selectedModifiers: input.selectedModifiers || [],
    selectedAddOns: input.selectedAddOns || [],
    specialInstructions: input.specialInstructions || '',
    quantity: qty,
    lineTotal: unitPrice * qty,
  };
}
```

