import React, { createContext, useReducer, useContext, useMemo } from 'react';
import { buildLineId, createCartLine, calculateLineUnitPrice } from '../utils/cartUtils';

// --- Initial State ---
const initialState = {
  /** @type {Object<string, CartLine>} */
  lines: {}, // Key = lineId (composite)
  // Derived: itemCount, subtotal calculated via selectors
};

// --- Reducer ---
function cartReducer(state, action) {
  switch (action.type) {
    case 'ADD_ITEM': {
      const { item } = action.payload; // item = CartItemInput
      const lineId = buildLineId(item); // **USE COMPOSITE ID**
      const existingLine = state.lines[lineId];

      let newLines;
      if (existingLine) {
        // CASE 2: Identical config -> Increment Quantity
        const newQty = existingLine.quantity + (item.quantity || 1);
        newLines = {
          ...state.lines,
          [lineId]: {
            ...existingLine,
            quantity: newQty,
            lineTotal: existingLine.lineTotal + (calculateLineUnitPrice(item) * (item.quantity || 1))
          }
        };
      } else {
        // CASE 1: New config -> New Line
        const newLine = createCartLine(item);
        newLines = { ...state.lines, [lineId]: newLine };
      }
      return { ...state, lines: newLines };
    }

    case 'REMOVE_LINE': {
      // Payload: { lineId } (Composite ID)
      const { lineId } = action.payload;
      if (!state.lines[lineId]) return state;
      const newLines = { ...state.lines };
      delete newLines[lineId];
      return { ...state, lines: newLines };
    }

    case 'UPDATE_QUANTITY': {
      // Payload: { lineId, quantity } (Composite ID)
      const { lineId, quantity } = action.payload;
      const line = state.lines[lineId];
      if (!line) return state;

      const newQty = Math.max(0, Math.floor(quantity));
      if (newQty === 0) {
        const newLines = { ...state.lines };
        delete newLines[lineId];
        return { ...state, lines: newLines };
      }

      const unitPrice = calculateLineUnitPrice(line); // Recalc from stored config
      return {
        ...state,
        lines: {
          ...state.lines,
          [lineId]: { ...line, quantity: newQty, lineTotal: unitPrice * newQty }
        }
      };
    }

    case 'CLEAR_CART':
      return initialState;

    default:
      return state;
  }
}

// --- Context & Provider ---
const CartContext = createContext(null);

export function CartProvider({ children }) {
  const [state, dispatch] = useReducer(cartReducer, initialState);

  // Memoized Actions (Stable references)
  const addItem = React.useCallback((item) => dispatch({ type: 'ADD_ITEM', payload: { item } }), []);
  const removeLine = React.useCallback((lineId) => dispatch({ type: 'REMOVE_LINE', payload: { lineId } }), []);
  const updateQuantity = React.useCallback((lineId, quantity) => dispatch({ type: 'UPDATE_QUANTITY', payload: { lineId, quantity } }), []);
  const clearCart = React.useCallback(() => dispatch({ type: 'CLEAR_CART' }), []);

  // Selectors (Derived State)
  const linesArray = useMemo(() => Object.values(state.lines), [state.lines]);
  const itemCount = useMemo(() => linesArray.reduce((sum, l) => sum + l.quantity, 0), [linesArray]);
  const subtotal = useMemo(() => linesArray.reduce((sum, l) => sum + l.lineTotal, 0), [linesArray]);

  return (
    <CartContext.Provider value={{ 
      lines: linesArray, // Array for rendering
      linesMap: state.lines, // Map for O(1) lookup if needed
      itemCount, 
      subtotal, 
      addItem, 
      removeLine, 
      updateQuantity, 
      clearCart 
    }}>
      {children}
    </CartContext.Provider>
  );
}

export function useCart() {
  const ctx = useContext(CartContext);
  if (!ctx) throw new Error('useCart must be used within CartProvider');
  return ctx;
}
```

